package org.sleepwell.app;
import org.junit.Test;import java.util.*;import java.util.concurrent.CancellationException;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
public final class HealthSleepSyncTest {
 final long now=10000000000L;HealthSleep remote(){return new HealthSleep("remote","com.other.sleep",now-3600000,now-1000,now,null,null,"","",List.of());}
 static final class Api implements HealthSleepPort {Access access=new Access(2,Set.of(READ,WRITE));int reads,changes,inserts,deletes;boolean expired,failInsert;Runnable afterRead=()->{};Map<String,Long> owned=new HashMap<>();public Access access(){return access;}public String token(){return "baseline";}public Page read(long start,long end,String page){reads++;afterRead.run();return new Page(List.of(),null);}public Changes changes(String token){changes++;return new Changes(List.of(),List.of(),"next-"+changes,false,expired&&token.equals("old"));}public String insert(String client,long version,HealthSleep sleep,boolean manual){inserts++;owned.merge(client,version,Math::max);if(failInsert)throw new IllegalStateException("Provider result lost after write");return "owned-id";}public void delete(String client){deletes++;owned.remove(client);}}
 final class Local implements HealthSleepSync.Local {String token="",last="";int applied;List<RecordEntry> records=new ArrayList<>();List<String> retired=new ArrayList<>();HealthSleepStore.Export pending;boolean ack;public String token(){return token;}public void apply(List<HealthSleep> r,List<String>d,String next,String own,long at){applied+=r.size();if(next!=null)token=next;}public List<RecordEntry> records(){return records;}public HealthSleepStore.Export prepare(RecordEntry r,String own){if(ack)return null;if(pending==null)pending=new HealthSleepStore.Export("stable",r.id,"birth",1,"fp",new HealthSleep("stable",own,r.edit.start,r.edit.end,1,0,0,"","",List.of()),true);return pending;}public void admit(HealthSleepStore.Export item){}public boolean ack(HealthSleepStore.Export item,String id){ack=true;return true;}public List<String> retired(){return retired;}public void retiredDone(String id){retired.remove(id);}public int conflicts(){return 0;}public void finished(long n,String s){last=s;}}
 RecordEntry record(String provenance){RecordDraft d=new RecordDraft(now-3600000,now-1000);return new RecordEntry(1,d.start,d.end,null,"manual","local","UTC",0,0,d,true,1,List.of(),"none","","",provenance);}
 @Test public void selectedPermissionsAreRecheckedBeforeAnyDataAccess(){Api api=new Api();api.access=new HealthSleepPort.Access(2,Set.of());Local local=new Local();assertThrows(SecurityException.class,()->new HealthSleepSync(api,local,"org.sleepwell.app").run(true,true,now,()->false));assertEquals(0,api.reads+api.inserts+api.changes);assertTrue(local.last.isEmpty());}
 @Test public void unavailableProviderCannotClaimConnectedOrSynced(){Api api=new Api();api.access=new HealthSleepPort.Access(1,Set.of());Local local=new Local();assertThrows(IllegalStateException.class,()->new HealthSleepSync(api,local,"org.sleepwell.app").run(true,false,now,()->false));assertTrue(local.last.isEmpty());}
 @Test public void importOnlyNeverWritesProviderAndStoresChangesAfterBaseline()throws Exception{Api api=new Api();Local local=new Local();new HealthSleepSync(api,local,"org.sleepwell.app").run(true,false,now,()->false);assertEquals(1,api.reads);assertEquals(1,api.changes);assertTrue(local.token.startsWith("next-"));assertEquals(0,api.inserts+api.deletes);assertFalse(local.last.isEmpty());}
 @Test public void exportOnlyNeedsOnlyWriteAndDoesNotReadProviderHistory()throws Exception{Api api=new Api();api.access=new HealthSleepPort.Access(2,Set.of(HealthSleepPort.WRITE));Local local=new Local();local.records.add(record(""));new HealthSleepSync(api,local,"org.sleepwell.app").run(false,true,now,()->false);assertEquals(1,api.inserts);assertEquals(0,api.reads+api.changes);assertTrue(local.ack);}
 @Test public void retryAfterAmbiguousWriteReusesStableIdentityVersion()throws Exception{Api api=new Api();api.failInsert=true;Local local=new Local();local.records.add(record(""));HealthSleepSync sync=new HealthSleepSync(api,local,"org.sleepwell.app");assertThrows(IllegalStateException.class,()->sync.run(false,true,now,()->false));assertEquals(Long.valueOf(1),api.owned.get("stable"));assertTrue(local.last.isEmpty());api.failInsert=false;sync.run(false,true,now,()->false);assertEquals(1,api.owned.size());assertEquals(2,api.inserts);assertTrue(local.ack);}
 @Test public void importedCopiesNeverFeedBackIntoExports()throws Exception{Api api=new Api();Local local=new Local();local.records.add(record("historical-provider-evidence"));new HealthSleepSync(api,local,"org.sleepwell.app").run(false,true,now,()->false);assertEquals(0,api.inserts);}
 @Test public void expiredChangesRebaselineWithoutDeletingOlderImportedHistory()throws Exception{Api api=new Api();api.expired=true;Local local=new Local();local.token="old";String result=new HealthSleepSync(api,local,"org.sleepwell.app").run(true,false,now,()->false);assertEquals(1,api.reads);assertTrue(result.contains("older imported copies were kept"));assertEquals(0,api.deletes);}
 @Test public void cancelAfterReadDoesNotApplyItsBatchOrAdvanceToken(){Api api=new Api();Local local=new Local();AtomicBoolean cancelled=new AtomicBoolean();api.afterRead=()->cancelled.set(true);assertThrows(CancellationException.class,()->new HealthSleepSync(api,local,"org.sleepwell.app").run(true,false,now,cancelled::get));assertEquals("",local.token);assertTrue(local.last.isEmpty());}
 @Test public void noSelectedDirectionsHasNoRemoteEffects(){Api api=new Api();Local local=new Local();assertThrows(IllegalArgumentException.class,()->new HealthSleepSync(api,local,"org.sleepwell.app").run(false,false,now,()->false));assertEquals(0,api.reads+api.inserts+api.changes);}
}
